import ("errors"; "time")

func WaitReady(ready <-chan struct{}) error {
    select {
    case <-ready: return nil
    case <-time.After(2 * time.Second): return errors.New("startup timed out")
    }
}

pub struct Directory { names: Vec<String> }

impl Directory {
    pub fn contains(&self, needle: &str) -> bool {
        self.names.to_owned().iter().any(|name| name == needle)
    }
}

type Axis = "x" | "y";

export function otherAxis(axis: Axis): Axis {
    return (axis === "x" ? "y" : "x") as Axis;
}

