import { z } from "zod";
const submission = z.object({ email: z.string().email(), age: z.number().int().min(18) });
export function parseSubmission(raw: unknown) { return submission.parse(raw); }

export function acceptSubmission(raw: unknown) {
    if (typeof raw !== "object" || raw === null || !("email" in raw) || !("age" in raw) || typeof raw.email !== "string" || typeof raw.age !== "number") {
        throw new Error("Invalid submission");
    }
    return { email: raw.email, age: raw.age };
}

use std::ffi::{CString, CStr, NulError};
fn consume_now(name: &CStr) -> usize { name.to_bytes().len() }

fn pin_name(name: &str) -> Result<&'static CStr, NulError> {
    let raw = CString::new(name)?.into_raw();
    Ok(unsafe { CStr::from_ptr(raw) })
}
pub fn handle_request(name: &str) -> Result<usize, NulError> {
    Ok(consume_now(pin_name(name)?))
}

use std::ffi::{CString, CStr, NulError};
fn consume_now(name: &CStr) -> usize { name.to_bytes().len() }

pub fn handle_request(name: &str) -> Result<usize, NulError> {
    let raw = CString::new(name)?.into_raw();
    let len = consume_now(unsafe { CStr::from_ptr(raw) });
    drop(unsafe { CString::from_raw(raw) });
    Ok(len)
}
